const PALETTE={red:'#b64937',blue:'#3c667c',green:'#61765a',gold:'#be964c',purple:'#78617b'};
export function studyScene(d){return `<svg class="study-scene" viewBox="0 0 720 420" role="img" aria-label="A study room: memorize the objects, colors, words, numbers and positions."><rect width="720" height="420" fill="#e5dfd2"/><path d="M0 325h720v95H0" fill="#c3ac8c"/><path d="M0 325h720M100 325 40 420m180-95-20 95m140-95 20 95m140-95 60 95" stroke="#ac9477"/><rect x="40" y="65" width="168" height="176" rx="2" fill="#f5f0e5" stroke="#8d8272" stroke-width="5"/><rect x="54" y="79" width="140" height="148" fill="#9fbbc1"/><path d="M124 80v148M54 153h140" stroke="#f5f0e5" stroke-width="6"/><path d="m54 175 38-40 35 27 30-45 37 50v60H54" fill="#70856a"/><circle cx="170" cy="105" r="15" fill="#e7c872"/>
<rect x="280" y="62" width="150" height="100" fill="#f8f4ea" stroke="#8e7c61" stroke-width="7"/><text x="355" y="105" text-anchor="middle" font-family="Georgia" font-size="25" fill="#3c4944">${d.word}</text><text x="355" y="137" text-anchor="middle" font-size="17" fill="#797163">EST. ${d.year}</text>
<circle cx="535" cy="100" r="39" fill="#f5f0e6" stroke="#574d42" stroke-width="5"/>${range(12).map(i=>`<circle cx="${535+Math.sin(i*Math.PI/6)*31}" cy="${100-Math.cos(i*Math.PI/6)*31}" r="1.6" fill="#574d42"/>`).join('')}<path d="M535 100 535 72M535 100 ${535+Math.sin(d.hour*Math.PI/6)*22} ${100-Math.cos(d.hour*Math.PI/6)*22}" stroke="#574d42" stroke-width="4" stroke-linecap="round"/>
<rect x="480" y="178" width="195" height="143" fill="#88715a"/><rect x="490" y="188" width="175" height="55" fill="#b9a58a"/><rect x="490" y="252" width="175" height="58" fill="#b9a58a"/>${range(d.books).map(i=>`<rect x="${500+i*19}" y="${197+i%3*5}" width="14" height="${44-i%3*5}" rx="1" fill="${Object.values(PALETTE)[i%5]}"/>`).join('')}<text x="585" y="285" fill="#f2e8d6" text-anchor="middle" font-size="16" letter-spacing="3">ARCHIVE ${d.archive}</text>
<path d="M202 268h270v18H202zM222 286v92m230-92v92" fill="#6f5540" stroke="#6f5540" stroke-width="8"/><rect x="288" y="239" width="75" height="28" rx="3" fill="${PALETTE[d.color]}"/><path d="M288 247h75M288 254h75M297 239v28" stroke="#e6d7b9" stroke-width="2"/>
${range(d.mugs).map(i=>`<g transform="translate(${382+i*33} 238)"><path d="M0 0h22v28H0z" fill="#f6eee0"/><path d="M22 5c18-2 18 19 0 17" fill="none" stroke="#f6eee0" stroke-width="5"/></g>`).join('')}
<path d="M245 235h31l-5 32h-21z" fill="#6a8477"/>${range(d.flowers).map(i=>`<path d="M260 242q${(i-2)*10} -20 ${(i-2)*8} -44" fill="none" stroke="#64744e" stroke-width="2"/><circle cx="${260+(i-2)*8}" cy="198" r="7" fill="#c77b68"/>`).join('')}
<rect x="54" y="294" width="76" height="18" fill="#55614d"/><path d="m61 312 10 58h42l10-58" fill="#ac7254"/><path d="M92 300v-61m0 42q-48-25-27-45 31 5 27 45m0-8q46-22 29-45-28 8-29 45" fill="#6b805b" stroke="#4c6344" stroke-width="4"/>
${range(d.cats).map(i=>`<g transform="translate(${500+i*61} 342)"><ellipse cx="20" cy="22" rx="19" ry="15" fill="${i?'#424641':'#c9a66c'}"/><path d="m7 6 0-16 10 10h8l9-10v18" fill="${i?'#424641':'#c9a66c'}"/><circle cx="14" cy="5" r="2" fill="#f9ead1"/><circle cx="27" cy="5" r="2" fill="#f9ead1"/><path d="M38 25q26 0 18-22" fill="none" stroke="${i?'#424641':'#c9a66c'}" stroke-width="7"/></g>`).join('')}
</svg>`;}
function memoryHide(s){s.phase='quiz';s.q=0;log(s,`The scene is hidden. Answer ${s.questions.length} questions.`);}
export const memory={create(s){s.scene={books:5+int(s,4),word:pick(s,['NORTH','QUIET','FOCUS','STUDY']),year:pick(s,[1924,1968,1984,2001]),hour:1+int(s,11),archive:10+int(s,80),color:pick(s,Object.keys(PALETTE)),mugs:1+int(s,2),flowers:3+int(s,3),cats:1+int(s,2)};let d=s.scene;s.questions=[['How many books are on the shelf?',d.books,range(4).map(i=>i+5)],['What word is in the framed print?',d.word,['NORTH','QUIET','FOCUS','STUDY']],['What year is written in the frame?',d.year,[1924,1968,1984,2001]],['What hour does the clock show?',d.hour,[d.hour,(d.hour+2)%12||12,(d.hour+5)%12||12,(d.hour+8)%12||12]],['What color is the book on the desk?',d.color,Object.keys(PALETTE)],['How many mugs are on the desk?',d.mugs,[1,2,3,4]],['How many flowers are in the vase?',d.flowers,[2,3,4,5]],['What is the archive number?',d.archive,[d.archive,d.archive+1,d.archive+10,d.archive-1]],['How many cats are in the room?',d.cats,[0,1,2,3]],['How many panes are in the window?',4,[2,3,4,6]]].map(([q,answer,options])=>({q,answer,options:shuffle(s,options)}));s.mistakes=0;if(s.difficulty==='relaxed')s.questions=[0,1,4,5,8,9].map(i=>s.questions[i]);if(s.difficulty==='hard')s.questions=shuffle(s,s.questions);s.studySeconds=tuning(s,'memory').study;s.phase='study';if(s.studySeconds)s.deadline=Date.now()+s.studySeconds*1000;else delete s.deadline;s.passes=tuning(s,'memory').passes;s.q=0;},view(s){if(s.phase==='study')return metrics(metric('Study time',s.difficulty==='relaxed'?'Untimed':`<span data-countdown>${s.studySeconds}s</span>`),metric('Questions',s.questions.length))+studyScene(s.scene)+controls(btn('I’m ready · hide the scene','hide','','primary'))+note('Look closely at objects, counts, colors, text and the clock. No notes once the scene is hidden.');let q=s.questions[Math.min(s.q,s.questions.length-1)];return metrics(metric('Question',`${Math.min(s.questions.length,s.q+1)} / ${s.questions.length}`),metric('Teammate passes',s.passes))+`<div class="question-scene"><span class="eyebrow">WHAT DO YOU REMEMBER?</span><h2>${q.q}</h2><div class="answer-grid">${q.options.map(v=>btn(esc(v),'answer',v,'answer')).join('')}</div></div>`+controls(btn('Pass to a teammate','pass','','',s.passes===0))+(s.difficulty==='relaxed'?`<details><summary>Practice: review the scene</summary>${studyScene(s.scene)}</details>`:'');},act(s,a,v){if(a==='hide'&&s.phase==='study'){memoryHide(s);return;}if(s.phase!=='quiz')return;if(a==='answer'||a==='pass'){let q=s.questions[s.q],correct=String(q.answer)===v;if(a==='pass'){if(!s.passes)return;s.passes--;correct=true;log(s,`Your teammate ${correct?'remembered the answer':'misremembered the scene'}.`);}if(!correct&&s.difficulty==='relaxed'){s.mistakes++;log(s,`The answer was ${q.answer}. Review the scene and try the next question.`);s.q++;if(s.q===s.questions.length)finish(s,true,'Study complete',`${s.questions.length-s.mistakes} of ${s.questions.length} recalled. Easy mode is for learning.`,10-s.mistakes);return;}if(!correct){finish(s,false,'One detail slipped away',`Question ${s.q+1}: ${q.q} The answer was ${q.answer}.`,s.q);return;}s.q++;log(s,'Correct. The next detail awaits.');if(s.q===s.questions.length)finish(s,true,'A perfect memory','All questions answered, including teammate passes.',s.questions.length);}},tick(s){if(s.phase==='study'&&s.difficulty!=='relaxed'&&Date.now()>=s.deadline){memoryHide(s);return true;}}};

export const WORD_BANK={Animals:['CAT','DOG','OWL','FOX','HEN','PIG','RAT','BAT','COW','ANT','BEE','ELK','APE','EMU','YAK','RAM','EWE','HARE','WOLF','BEAR','LION','DEER','SEAL','GOAT','FROG','CRAB','DUCK','SWAN'],Colors:['RED','BLUE','GREEN','GOLD','PINK','WHITE','BLACK','GRAY','BROWN','CYAN','TEAL','LIME','NAVY','PLUM','ROSE'],Food:['RICE','BEAN','PEAR','PLUM','LIME','CORN','CAKE','SOUP','BREAD','APPLE','GRAPE','PEACH','MANGO','LEMON','MELON','OLIVE','ONION','SALAD','TOAST']};
function wordDeal(s){s.category=Object.keys(WORD_BANK)[s.round-1];s.solution=shuffle(s,WORD_BANK[s.category].filter(w=>w.length>=tuning(s,'words').min&&w.length<=tuning(s,'words').max)).slice(0,tuning(s,'words').count);s.pool=shuffle(s,s.solution.join('').split(''));s.used=[];s.helpCount=0;}
function consume(pool,word){let a=[...pool];for(let l of word){let i=a.indexOf(l);if(i<0)return null;a.splice(i,1);}return a;}
export const words={create(s){s.round=1;wordDeal(s);},view(s){return metrics(metric('Round',`${s.round} / 3`),metric('Category',s.category),metric('Words built',`${s.used.length} / ${tuning(s,'words').count}`))+`<div class="letter-pool">${s.pool.map(l=>`<span>${l}</span>`).join('')}</div><div class="word-towers">${s.used.map((w,i)=>`<button data-act="undo" data-value="${i}" class="word-built" title="Return letters to pool">${w}<small>↶ return</small></button>`).join('')}</div>`+controls(`<label class="field grow">Your word<input id="word" type="text" maxlength="10" placeholder="Build a category word" autocomplete="off" spellcheck="false"></label>`,btn('Build word','word','','primary'),btn(`Ask teammate · ${tuning(s,'words').help-(s.helpCount||0)} left`,'help','','',(s.helpCount||0)>=tuning(s,'words').help))+`<details class="dictionary"><summary>Accepted ${s.category.toLowerCase()} dictionary</summary><p>${WORD_BANK[s.category].join(' · ')}</p></details>`+note(`Use every letter in exactly ${tuning(s,'words').count} different words. Return any built word if stuck. Teammate contributions this round: ${tuning(s,'words').help}.`);},act(s,a,v,p){let w=(p.word||'').trim().toUpperCase();if(a==='undo'){s.pool.push(...s.used.splice(+v,1)[0]);return;}if(a==='help'){if((s.helpCount||0)>=tuning(s,'words').help)return;let options=WORD_BANK[s.category].filter(w=>!s.used.includes(w)&&consume(s.pool,w));w=s.solution.find(w=>options.includes(w))||options[0];if(!w){error(s,'Your teammate cannot form a word from the remaining letters. Try returning a word.');return;}s.helpCount=(s.helpCount||0)+1;log(s,`Mira contributed ${w}.`);}else if(a!=='word')return;if(!WORD_BANK[s.category].includes(w)){error(s,'Choose a word from this category’s accepted dictionary.');return;}if(s.used.includes(w)){error(s,'Each word must be different.');return;}let pool=consume(s.pool,w);if(!pool){error(s,'That word needs letters that are not in the pool.');return;}if(s.used.length===tuning(s,'words').count){error(s,'Return a word before adding another.');return;}s.pool=pool;s.used.push(w);if(s.used.length===tuning(s,'words').count&&!s.pool.length){if(s.round===3)finish(s,true,'A tower of possibilities','All letters used across all three rounds.',tuning(s,'words').count*3);else{s.round++;wordDeal(s);log(s,'Every letter used. A new category is ready.');}}}};

const MINERALS=['Red','Gold','Green','Blue','Violet'];
export const scale={
create(s){s.weights=shuffle(s,range(tuning(s,'scale').max).map(i=>i+1)).slice(0,5);s.left=[0,0,0,0,0];s.right=[0,0,0,0,0];s.weighings=0;s.limit=tuning(s,'scale').limit;s.history=[];s.bounds=range(5).map(()=>[1,tuning(s,'scale').max]);for(let i=0;i<tuning(s,'scale').known;i++)s.bounds[i]=[s.weights[i],s.weights[i]];s.balanced=false;},
view(s){return metrics(metric('Weighings left',s.limit-s.weighings),metric('Known minerals',s.weights.slice(0,tuning(s,'scale').known).map((w,i)=>MINERALS[i]+' = '+w+'g').join(' · ')),metric('Balanced test',s.balanced?'Recorded':'Needed'))+note('Calibration edition: reusable minerals and a 1g reference mass replace the show’s accumulating pans. Compare an unknown to a chosen number of grams; use heavier/lighter results to narrow its range. No weights are given away.')+controls(select('mineral','Mineral',MINERALS.map((m,i)=>[i,m]),tuning(s,'scale').known),input('reference','Reference mass (g)',Math.ceil(tuning(s,'scale').max/2),1,tuning(s,'scale').max),btn('Compare to reference','compare','','primary',s.weighings>=s.limit))+(tuning(s,'scale').bounds?`<div class="contact-list">${s.bounds.map(([lo,hi],i)=>`<div><b>${MINERALS[i]}</b><span>${lo===hi?lo+'g':lo+'–'+hi+'g'}</span></div>`).join('')}</div>`:note('Hard: keep your own range notes from the weighing history. All weights are integers from 1 to 20g.'))+`<details><summary>Optional mineral-to-mineral pans</summary><div class="scale-editor">${[s.left,s.right].map((pan,k)=>`<div><h3>${k?'Right':'Left'}</h3>${pan.map((n,i)=>`<div class="mineral-control"><span>${MINERALS[i]}</span>${btn('−','pan',`${k},${i},-1`,'',!n)}<b>${n}</b>${btn('+','pan',`${k},${i},1`,'',n>=20)}</div>`).join('')}</div>`).join('')}</div>${controls(btn('Weigh pans','weigh'),btn('Clear pans','clear'))}</details><div class="contact-list">${s.history.map(h=>`<div><span>${esc(h.left)}</span><b>${esc(h.result)}</b><span>${esc(h.right)}</span></div>`).join('')}</div><h3>Declare the five weights</h3><p>Record at least one equal weighing first. A wrong declaration uses one weighing; you can keep investigating.</p><div class="input-row">${MINERALS.map((m,i)=>input('weight'+i,m,i<tuning(s,'scale').known?s.weights[i]:'',1,tuning(s,'scale').max)).join('')}</div>`+controls(btn('Submit deductions','submit','','primary'));},
act(s,a,v,p){if(a==='pan'){let [side,i,d]=v.split(',').map(Number),pan=side?s.right:s.left;pan[i]=Math.max(0,Math.min(20,pan[i]+d));return;}if(a==='clear'){s.left.fill(0);s.right.fill(0);return;}if(a==='submit'){let values=range(5).map(i=>parseIntField(p,'weight'+i,1,tuning(s,'scale').max));if(values.includes(null)){error(s,`Enter all five integer weights, from 1 to ${tuning(s,'scale').max}g.`);return;}if(!s.balanced){error(s,'First record an equal weighing using different compositions, or a mineral against a reference mass.');return;}if(values.every((x,i)=>x===s.weights[i]))finish(s,true,'A balanced deduction',s.weights.map((w,i)=>`${MINERALS[i]} ${w}g`).join(' · '),5);else{s.weighings++;error(s,'Those weights are not all correct. One weighing spent; keep investigating.');} }
if(['weigh','compare'].includes(a)&&s.weighings<s.limit){let x,y,left,right;if(a==='compare'){let i=parseIntField(p,'mineral',0,4),ref=parseIntField(p,'reference',1,tuning(s,'scale').max);if(i===null||ref===null)return;x=s.weights[i];y=ref;left=MINERALS[i];right=ref+'g reference';let b=s.bounds[i];if(x===y)s.bounds[i]=[ref,ref];else if(x<y)b[1]=Math.min(b[1],ref-1);else b[0]=Math.max(b[0],ref+1);}else{if(!s.left.some(Boolean)||!s.right.some(Boolean)||s.left.every((n,i)=>n===s.right[i])){error(s,'Put different nonempty mineral compositions on the two pans.');return;}let sum=pan=>pan.reduce((n,c,i)=>n+c*s.weights[i],0);x=sum(s.left);y=sum(s.right);let describe=pan=>pan.map((n,i)=>n?`${n} ${MINERALS[i]}`:'').filter(Boolean).join(' + ');left=describe(s.left);right=describe(s.right);}s.last=x===y?'=':x<y?'<':'>';s.balanced ||= x===y;s.weighings++;s.history.unshift({left,right,result:s.last});log(s,`${left} ${s.last} ${right}.`);}
if(s.weighings>=s.limit&&!s.outcome)finish(s,false,'The weighing budget is spent','Try halving the remaining range each time. '+s.weights.map((w,i)=>`${MINERALS[i]} ${w}g`).join(' · '),0);
}};

export function portrait(id){let hair=['#342d29','#78604a','#b09a72','#544844'][id%4],shirt=['#788876','#a67f6c','#667e88','#a8956c'][Math.floor(id/4)%4],skin=['#e2ba94','#be8d6a','#efd0ad'][Math.floor(id/16)%3],glasses=Math.floor(id/3)%2,style=Math.floor(id/7)%3;return `<svg viewBox="0 0 280 300" class="portrait" role="img" aria-label="Portrait to remember"><rect width="280" height="300" rx="4" fill="#ded8cc"/><circle cx="140" cy="126" r="101" fill="#eae5dc"/><path d="M35 300v-32q3-67 105-67t105 67v32" fill="${shirt}"/><path d="M121 181v38q20 22 39 0v-38" fill="${skin}"/><ellipse cx="140" cy="123" rx="62" ry="79" fill="${hair}"/><ellipse cx="140" cy="139" rx="53" ry="65" fill="${skin}"/><path d="${style===0?'M83 112Q73 42 140 42T198 112Q161 105 147 72Q129 104 83 112Z':style===1?'M83 112Q73 42 140 42T198 112L162 91 146 69 117 96Z':'M83 112Q73 42 140 42T198 112Q162 87 140 70Q111 98 83 112Z'}" fill="${hair}"/><ellipse cx="117" cy="139" rx="4" ry="3" fill="#443a32"/><ellipse cx="162" cy="139" rx="4" ry="3" fill="#443a32"/><path d="m139 142-5 20h9m-20 17q17 ${id%2?'-8':'9'} 34 0" fill="none" stroke="#8f624e" stroke-width="2.5" stroke-linecap="round"/>${glasses?'<g fill="none" stroke="#4d4940" stroke-width="3"><rect x="99" y="127" width="36" height="25" rx="8"/><rect x="146" y="127" width="36" height="25" rx="8"/><path d="M135 136h11"/></g>':''}<path d="m113 221 27 27 28-27M140 248v52" fill="none" stroke="#e9e1d2" stroke-width="3"/></svg>`;}
function montageDeal(s){let faces=shuffle(s,range(48)).slice(0,tuning(s,'montage').faces+Math.min(s.round,4));let repeatAt=4+int(s,faces.length-3);let repeated=faces[int(s,repeatAt)];faces.splice(repeatAt,0,repeated);s.faces=faces;s.buzzed=false;s.index=0;s.seen=[];s.deadline=Date.now()+(tuning(s,'montage').seconds||5)*1000;s.phase='watch';}
function montageAdvance(s,answer){let current=s.faces[s.index],repeat=s.seen.includes(current);if(answer){if(repeat){s.round++;if(s.round>tuning(s,'montage').rounds)finish(s,true,'A face you won’t forget',`You caught the repeated portrait in all ${tuning(s,'montage').rounds} rounds.`,tuning(s,'montage').rounds);else{log(s,'Repeat identified. A new sequence begins.');montageDeal(s);}return;}if(s.buzzed)return;s.buzzed=true;s.mistakes++;log(s,'False buzz. This was a new face. Wait or choose New face.');if(s.mistakes>=10){finish(s,false,'Too many false alarms','Ten false buzzes ended the match.',s.round-1);return;}return;}else if(repeat){if(s.difficulty==='relaxed'){log(s,'Practice review: this was a repeat. Study the next sequence.');s.round++;if(s.round>tuning(s,'montage').rounds)finish(s,true,'A team effort',`Completed ${tuning(s,'montage').rounds} practice sequences, including review rounds.`,tuning(s,'montage').rounds);else montageDeal(s);}else finish(s,false,'A familiar face slipped past',`You missed the repeat in round ${s.round}.`,s.round-1);return;}s.seen.push(current);s.buzzed=false;s.index++;if(s.index>=s.faces.length){finish(s,false,'The sequence ended','No repeat was identified.',s.round-1);return;}s.deadline=Date.now()+(tuning(s,'montage').seconds||5)*1000;}
export const montage={create(s){s.round=1;s.mistakes=0;s.phase='ready';},view(s){if(s.phase==='ready')return `<div class="center-intro"><span class="eyebrow">LOOK CLOSER</span><h2>Some faces<br>stay with you.</h2><p>${s.difficulty==='relaxed'?'Easy mode: you decide when to advance.':'Standard: five seconds per portrait. Hard: three seconds.'} Look for an exact repeat.</p>${btn('Start the sequence','start','','primary')}</div>`;return metrics(metric('Round',`${Math.min(tuning(s,'montage').rounds,s.round)} / ${tuning(s,'montage').rounds}`),metric('False buzzes',`${s.mistakes} / 10`),metric('Portrait',s.index+1))+`<div class="portrait-stage">${portrait(s.faces[s.index])}<span class="portrait-caption">${s.difficulty==='relaxed'?'TAKE YOUR TIME':`<span data-countdown>${s.difficulty==='hard'?3:5}s</span> · OBSERVE`}</span></div>`+controls(btn('Seen before · Space','buzz','','primary',s.buzzed),btn('New face →','next'))+(s.difficulty==='relaxed'?`<details open class="seen-faces"><summary>Faces already seen this round</summary><div>${s.seen.map(portrait).join('')||'<p>No earlier faces yet.</p>'}</div></details>`:'')+note('Match the whole portrait: hairstyle, glasses, clothing, complexion and expression. Faces can look very similar.');},act(s,a){if(a==='start'&&s.phase==='ready'){montageDeal(s);return;}if(s.phase!=='watch')return;if(a==='buzz')montageAdvance(s,true);if(a==='next')montageAdvance(s,false);},tick(s){if(s.phase==='watch'&&s.difficulty!=='relaxed'&&Date.now()>=s.deadline){montageAdvance(s,false);return true;}}};

export const THREE_LINES=lineSets(4,3);
export function threeWinners(stacks){let top=stacks.map(s=>s.at(-1)??-1);return [...new Set(THREE_LINES.filter(l=>top[l[0]]!==-1&&l.every(i=>top[i]===top[l[0]])).map(l=>top[l[0]]))];}
export function threeMoves(s,p){let moves=[];for(let i=0;i<16;i++){if(s.stacks[i].length<3&&s.reserves[p]>0)moves.push({from:-1,to:i});if(s.stacks[i].at(-1)===p)for(let j of neighbors(i,4,true))if(s.stacks[j].length<3)moves.push({from:i,to:j});}return moves;}
export function threeApply(s,p,m){if(m.from===-1)s.reserves[p]--;else s.stacks[m.from].pop();s.stacks[m.to].push(p);}
function threeDeal(s){s.stacks=range(16).map(()=>[]);s.reserves=[5,5,5,5];s.selected=-1;s.mode='place';s.moves=0;}
function threeCheck(s){let winners=threeWinners(s.stacks);if(winners.includes(3)){finish(s,false,'The guest found a line',`Blue won in round ${s.round}.`,s.round-1);return true;}if(winners.length){log(s,`${winners.map(i=>['You','Mira','Sage','Guest'][i]).join(' and ')} formed a line. Guest blocked.`);s.round++;if(s.round>(s.difficulty==='relaxed'?1:4))finish(s,true,'No invitation for the guest','Your team completed the cooperative mission.',tuning(s,'three').rounds);else threeDeal(s);return true;}if(s.moves>=80){finish(s,false,'A locked board','Eighty moves without a winning line ended the solo mission.',s.round-1);return true;}return false;}
function threeBot(s,p){let moves=threeMoves(s,p);if(!moves.length){log(s,`${['You','Mira','Sage','Guest'][p]} passed.`);return;}let best=-Infinity,chosen=moves[0];for(let m of moves){let b={stacks:s.stacks.map(x=>[...x]),reserves:[...s.reserves]};threeApply(b,p,m);let wins=threeWinners(b.stacks);let score=((p===3?wins.includes(3):wins.some(w=>w!==3))?1000:0)+(p!==3&&wins.includes(3)?-2000:0);let guestThreats=0;for(let gm of p===3?[]:threeMoves(b,3)){let c={stacks:b.stacks.map(x=>[...x]),reserves:[...b.reserves]};threeApply(c,3,gm);if(threeWinners(c.stacks).includes(3))guestThreats++;}score-=guestThreats*30;if(p===3&&tuning(s,'three').lookahead){let replies=threeMoves(b,0);if(replies.some(reply=>{let next={stacks:b.stacks.map(x=>[...x]),reserves:[...b.reserves]};threeApply(next,0,reply);return threeWinners(next.stacks).some(w=>w!==3);}))score-=300;}let top=b.stacks.map(x=>x.at(-1));score+=THREE_LINES.reduce((sum,l)=>sum+(l.filter(i=>top[i]===p).length===2?6:0),0)+random(s)*(p===3?tuning(s,'three').guestNoise:2);if(score>best){best=score;chosen=m;}}threeApply(s,p,chosen);s.moves++;log(s,`${['You','Mira','Sage','Guest'][p]} ${chosen.from===-1?'placed':'moved'} at ${Math.floor(chosen.to/4)+1},${chosen.to%4+1}.`);}
export const three={create(s){s.round=1;threeDeal(s);},view(s){let names=['You','Mira','Sage','Guest'];return metrics(metric('Round',`${Math.min(s.difficulty==='relaxed'?1:4,s.round)} / ${s.difficulty==='relaxed'?1:4}`),metric('Your reserve',s.reserves[0]),metric('Moves',s.moves))+`<div class="legend">${names.map((n,i)=>`<span><i class="dot p${i}"></i>${n}</span>`).join('')}</div>`+grid(4,s.stacks.map((st,i)=>cell(i,st.length?`<span class="stack">${st.map(p=>`<i class="p${p}"></i>`).join('')}</span><small class="stack-height">${st.length}/3</small>`:'<span class="empty-dot">·</span>',`${i===s.selected?'selected':''}`)),'three-board')+controls(btn('Place new piece','new-mode','',s.mode==='place'?'selected':''),btn('Move exposed piece','move-mode','',s.mode==='move'?'selected':''),btn('Pass (only if no legal moves)','pass','','',threeMoves(s,0).length>0))+note(s.selected>=0?'Select an adjacent destination (including diagonals). The destination stack must be shorter than three.':'Click a square to place a red piece. Choose Move exposed piece to select a red top piece for a move. Blue is the guest.');},act(s,a,v){if(a==='new-mode'||a==='move-mode'){s.selected=-1;s.mode=a==='new-mode'?'place':'move';return;}let made=false;if(a==='cell'){let i=+v;if(s.selected===i){s.selected=-1;return;}if(s.selected<0&&s.stacks[i].at(-1)===0&&s.mode==='move'){s.selected=i;return;}if(s.selected<0&&s.mode==='move'){error(s,'Select one of your exposed red pieces first.');return;}let move={from:s.selected,to:i};if(!threeMoves(s,0).some(m=>m.from===move.from&&m.to===move.to)){error(s,'Place from your reserve or move an exposed red piece to an adjacent stack below height three.');return;}threeApply(s,0,move);made=true;}if(a==='pass'&&!threeMoves(s,0).length)made=true;if(!made)return;s.selected=-1;s.mode='place';s.moves++;if(threeCheck(s))return;for(let p=1;p<4;p++){threeBot(s,p);if(threeCheck(s))return;}}};
